"""Wire ``on_model_response`` / ``modify_model_response`` for one LLM iteration."""

from __future__ import annotations

from typing import List, NamedTuple, Optional

import structlog

from rasa.mantle.hooks.constants import POINT_MODEL_RESPONSE
from rasa.mantle.hooks.exceptions import HookExecutionError, RetryModel
from rasa.mantle.hooks.payloads import ModelResponsePayload
from rasa.mantle.hooks.registry import HookRegistry
from rasa.mantle.hooks.runner import run_modify, run_observers
from rasa.mantle.hooks.utils import hook_identity
from rasa.shared.providers.llm.llm_response import LLMToolCall

structlogger = structlog.get_logger()


class ModelResponseHookResult(NamedTuple):
    """Outcome of applying model-response hooks before user-visible effects."""

    text: Optional[str]
    tool_calls: List[LLMToolCall]
    retry: Optional[RetryModel] = None


def _tool_call_to_dict(tool_call: LLMToolCall) -> dict:
    return {
        "id": tool_call.id,
        "tool_name": tool_call.tool_name,
        "tool_args": dict(tool_call.tool_args),
        "type": tool_call.type,
    }


def _tool_calls_from_payload(raw_calls: list) -> List[LLMToolCall]:
    """Parse payload tool-call dicts back into engine ``LLMToolCall`` values.

    Raises:
        HookExecutionError: When a returned entry is not a valid tool call.
    """
    parsed: List[LLMToolCall] = []
    for index, entry in enumerate(raw_calls):
        if not isinstance(entry, dict):
            raise HookExecutionError(
                "modify_model_response returned a non-dict tool call "
                f"at index {index}."
            )
        try:
            parsed.append(
                LLMToolCall(
                    id=str(entry["id"]),
                    tool_name=str(entry["tool_name"]),
                    tool_args=dict(entry.get("tool_args") or {}),
                    type=str(entry.get("type") or "function"),
                )
            )
        except (KeyError, TypeError, ValueError) as exc:
            raise HookExecutionError(
                "modify_model_response returned an invalid tool call "
                f"at index {index}."
            ) from exc
    return parsed


async def apply_model_response_hooks(
    registry: HookRegistry,
    *,
    text: Optional[str],
    tool_calls: List[LLMToolCall],
    latency_ms: Optional[float],
) -> ModelResponseHookResult:
    """Run ``on_model_response`` / ``modify_model_response`` for this iteration.

    Observers fire-and-forget. The modify lane may rewrite ``text`` and
    ``tool_calls``. ``RetryModel`` is intentional control flow and is returned
    to the caller — it must not be treated as fail-open. Unexpected modifier
    crashes, timeouts, or invalid returns are fail-open and keep the original
    response. Unsupported ``HookRejection`` (raised by the runner as
    ``HookExecutionError`` until the control-flow contract lands) is treated
    as fail-open here so the original response proceeds.
    """
    if (
        not registry.observers(POINT_MODEL_RESPONSE)
        and registry.modifier(POINT_MODEL_RESPONSE) is None
    ):
        return ModelResponseHookResult(text=text, tool_calls=list(tool_calls))

    try:
        sender_id, channel = hook_identity()
    except LookupError:
        # Live turns establish MessageTurnContext; missing context is misuse
        # (e.g. isolated unit tests). Keep the response unmodified.
        structlogger.warning(
            "mantle.hooks.model_response.skipped_no_turn_context",
        )
        return ModelResponseHookResult(text=text, tool_calls=list(tool_calls))

    payload = ModelResponsePayload(
        sender_id=sender_id,
        channel=channel,
        text=text,
        tool_calls=[_tool_call_to_dict(tc) for tc in tool_calls],
        latency_ms=latency_ms,
    )

    run_observers(registry, POINT_MODEL_RESPONSE, payload)
    try:
        result = await run_modify(registry, POINT_MODEL_RESPONSE, payload)
    except HookExecutionError:
        return ModelResponseHookResult(text=text, tool_calls=list(tool_calls))

    if isinstance(result.control_flow, RetryModel):
        return ModelResponseHookResult(
            text=text,
            tool_calls=list(tool_calls),
            retry=result.control_flow,
        )

    modified = result.payload
    if not isinstance(modified, ModelResponsePayload):
        # Fail-open: keep the original response rather than aborting the turn.
        return ModelResponseHookResult(text=text, tool_calls=list(tool_calls))

    try:
        return ModelResponseHookResult(
            text=modified.text,
            tool_calls=_tool_calls_from_payload(modified.tool_calls),
        )
    except HookExecutionError:
        return ModelResponseHookResult(text=text, tool_calls=list(tool_calls))
